for part in (1, 2):
    tl = json.load(open(f"{H}/tl_p{part}.json")); mk = tl["marks"]
    out += [f"## Part {part} · \"{TITLES[part]}\" · {fm(tl['END'])}", ""]
    for sc in tl["scenes"]:
        n = NOTES[part].get(sc["name"], ("(no notes)", "", "", ""))
        ms = sorted((v, k) for k, v in mk.items() if sc["t0"] <= v < sc["t1"])
        lines = [i for i in tl["order"] if sc["t0"] - .01 <= tl["lines"][i]["t"] < sc["t1"]]
        out += [f"### {fm(sc['t0'])} – {fm(sc['t1'])} · `{sc['name']}` · {n[0]} ({sc['t1'] - sc['t0']:.1f} s)", ""]
        if n[1]: out.append(f"- **Draw:** {n[1]}")
        out.append(f"- **Reuse:** {n[2]}")
        out.append(f"- **New:** {n[3]}")
        if ms: out.append("- **Marks:** " + ", ".join(f"`{k}` {fm(v)}" for v, k in ms))
        if lines:
            out.append("- **Lines:**")
            for i in lines:
                L = tl["lines"][i]; out.append(f"  - `{i}` {fm(L['t'])} {L['who'].upper()}: {L['text'] if L['who'] != 'chant' or i != 'c1003' else 'the chant (3 calls, YOUR TURN! after each)'}")
        out.append("")
open(f"{H}/SCENES_TODO.md", "w").write("\n".join(out))
missing = [(p, s["name"]) for p in (1, 2) for s in json.load(open(f"{H}/tl_p{p}.json"))["scenes"] if s["name"] not in NOTES[p]]
print("SCENES_TODO.md:", sum(len(json.load(open(f"{H}/tl_p{p}.json"))["scenes"]) for p in (1, 2)), "scenes", "missing notes:", missing)
